#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;

struct Cell {
    int row;
    int col;
};

long long mod_pow(long long base, long long exponent) {
    long long result = 1;
    while (exponent > 0) {
        if (exponent & 1) result = result * base % MOD;
        base = base * base % MOD;
        exponent >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<Cell> cells;
    cells.reserve(m);
    for (int c = 0; c < m; ++c) {
        Cell cell;
        cin >> cell.row >> cell.col;
        cells.push_back(cell);
    }

    sort(cells.begin(), cells.end(), [](const Cell& a, const Cell& b) {
        const int diagonal_a = a.row + a.col;
        const int diagonal_b = b.row + b.col;
        if (diagonal_a != diagonal_b) return diagonal_a < diagonal_b;
        if (a.row != b.row) return a.row < b.row;
        return a.col < b.col;
    });
    cells.erase(unique(cells.begin(), cells.end(), [](const Cell& a, const Cell& b) {
        return a.row == b.row && a.col == b.col;
    }), cells.end());

    bool blocked_start = false;
    bool blocked_finish = false;
    for (const Cell& cell : cells) {
        if (cell.row == 0 && cell.col == 0) blocked_start = true;
        if (cell.row == n - 1 && cell.col == n - 1) blocked_finish = true;
    }
    if (blocked_start || blocked_finish) {
        cout << 0 << '\n';
        return 0;
    }

    const int max_steps = 2 * (n - 1);
    vector<int> factorial(max_steps + 1, 1);
    vector<int> inverse_factorial(max_steps + 1, 1);
    for (int i = 1; i <= max_steps; ++i) {
        factorial[i] = static_cast<long long>(factorial[i - 1]) * i % MOD;
    }
    inverse_factorial[max_steps] = static_cast<int>(mod_pow(factorial[max_steps], MOD - 2));
    for (int i = max_steps; i > 0; --i) {
        inverse_factorial[i - 1] = static_cast<long long>(inverse_factorial[i]) * i % MOD;
    }

    auto choose = [&](int total, int selected) -> long long {
        if (selected < 0 || selected > total) return 0;
        return static_cast<long long>(factorial[total]) * inverse_factorial[selected] % MOD
             * inverse_factorial[total - selected] % MOD;
    };

    const int distinct = static_cast<int>(cells.size());
    vector<int> ways(distinct, 0);
    auto compute_blocked_cell = [&](int index, int previous_count) {
        const Cell& cell = cells[index];
        long long blocked_paths = 0;
        for (int q = 0; q < previous_count; ++q) {
            const Cell& previous = cells[q];
            if (previous.row > cell.row || previous.col > cell.col) continue;
            const int dr = cell.row - previous.row;
            const int dc = cell.col - previous.col;
            blocked_paths += static_cast<long long>(ways[q]) * choose(dr + dc, dc) % MOD;
            if (blocked_paths >= MOD) blocked_paths -= MOD;
        }
        long long value = choose(cell.row + cell.col, cell.col) - blocked_paths;
        if (value < 0) value += MOD;
        ways[index] = static_cast<int>(value);
    };

    int begin = 0;
    while (begin < distinct) {
        int end = begin + 1;
        const int diagonal = cells[begin].row + cells[begin].col;
        while (end < distinct && cells[end].row + cells[end].col == diagonal) ++end;

        const int batch_size = end - begin;
        const long long estimated_work = static_cast<long long>(batch_size) * begin;
        if (batch_size >= 8 && estimated_work >= 8192) {
            #pragma omp parallel for schedule(static)
            for (int index = begin; index < end; ++index) {
                compute_blocked_cell(index, begin);
            }
        } else {
            for (int index = begin; index < end; ++index) {
                compute_blocked_cell(index, begin);
            }
        }
        begin = end;
    }

    long long result = choose(max_steps, n - 1);
    for (int i = 0; i < distinct; ++i) {
        const int dr = n - 1 - cells[i].row;
        const int dc = n - 1 - cells[i].col;
        const long long contribution = static_cast<long long>(ways[i]) * choose(dr + dc, dc) % MOD;
        result -= contribution;
        if (result < 0) result += MOD;
    }

    cout << result << '\n';
    return 0;
}
